SINA_SMART["hemato1-splenomegaly"] = {"lecture":"hemato1-splenomegaly","title":"Splenomegaly","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"hemato1-splenomegaly:e0","text":"Normal spleen: not palpable; 12 × 7 cm, < 250 g, 9th-11th left ribs.","topic":"Definition and the normal spleen","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-splenomegaly:e1","text":"Palpable spleen = always pathological.","topic":"Definition and the normal spleen","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-splenomegaly:e2","text":"Spleen roles: IgM, filter, pools 30-40% of platelets, iron recycling, fetal haematopoiesis.","topic":"Definition and the normal spleen","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-splenomegaly:e3","text":"Hypersplenism: mild cytopenias + rich marrow + big spleen, corrected by splenectomy.","topic":"Hypersplenism","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-splenomegaly:e4","text":"Signs: moves with respiration, notched anterior edge.","topic":"Symptoms, signs and differential diagnosis","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-splenomegaly:e5","text":"Differential: left kidney, pancreatic tail, left colic angle, stomach tumours.","topic":"Symptoms, signs and differential diagnosis","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-splenomegaly:e6","text":"Mechanisms: hyperplasia, congestion, infiltration.","topic":"Mechanisms and step-wise approach","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-splenomegaly:e7","text":"CBC + film + abdominal ultrasound explain ~90% of cases.","topic":"Mechanisms and step-wise approach","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-splenomegaly:e10","text":"Infiltration: CML, myelofibrosis, CLL, lymphoma; Gaucher, amyloidosis.","topic":"Aetiologies","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-splenomegaly:e8","text":"Infections: mononucleosis, endocarditis, typhoid, brucellosis, malaria, kala-azar.","topic":"Aetiologies","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-splenomegaly:e9","text":"Congestion: cirrhosis, portal thrombosis, Budd-Chiari, right heart failure.","topic":"Aetiologies","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"zys23r":"a","1dep6gw":"a","1nczwv5":"a","1md3vie":"a","v7bspj":"a","1y4o8kh":"a","1ttyuwv":"a","dfymuz":"a","1vsb7jn":"a","h12v2v":"a","10fx7e8":"a","ow5i78":"a","1qmit6h":"a","oxq4r6":"a","rmjdbl":"x"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"hemato1-splenomegaly:e0":{"s":0,"u":["Normal spleen: not palpable; 12 × 7 cm, < 250 g, 9th-11th left ribs.","Normal spleen: about 12 cm long, 7 cm wide, under 250 g , along the 9th-11th left ribs , with notches on its anterior edge, moving down on inspiration.","Three fundamentals: a normal spleen is not palpable ; a splenomegaly is palpable; so a palpable spleen is always pathological and needs a reasoned search for the cause."],"dp":[]},"hemato1-splenomegaly:e1":{"s":0,"u":["Palpable spleen = always pathological.","Three fundamentals: a normal spleen is not palpable ; a splenomegaly is palpable; so a palpable spleen is always pathological and needs a reasoned search for the cause."],"dp":[]},"hemato1-splenomegaly:e2":{"s":0,"u":["Spleen roles: IgM, filter, pools 30-40% of platelets, iron recycling, fetal haematopoiesis.","Functions: immune (processes antigens, major site of IgM production, opsonises bacteria and fungi), filter (macrophages remove old red cells and platelets), pooling (30-40% of platelets), iron recycling from haemoglobin, and haematopoiesis in the fetus."],"dp":[]},"hemato1-splenomegaly:e3":{"s":1,"u":["Hypersplenism: mild cytopenias + rich marrow + big spleen, corrected by splenectomy.","A large spleen can cause hypersplenism : (1) mild cytopenias , alone or combined: normochromic normocytic regenerative anaemia , thrombocytopenia, leucopenia affecting all white cells (the differential is preserved), usually without clinical signs; (2) a hypercellular bone marrow reacting to the peripheral loss; (3) the splenomegaly itself; (4) correction of the cytopenias after splenectomy ."],"dp":[{"h":"Why splenectomy patients need vaccines","t":"The spleen is where IgM is made against capsular polysaccharides and where opsonised bacteria are cleared. Without it (splenectomy for hypersplenism, trauma or ITP), patients are at lifelong risk of overwhelming post-splenectomy infection by encapsulated bacteria: Streptococcus pneumoniae , Haemophilus influenzae type b and Neisseria meningitidis . That is why they are vaccinated against all three, ideally at least two weeks before an elective splenectomy, and taught to seek care urgently for any fever. Source: the lecture's immune functions of the spleen; standard post-splenectomy guidance."}]},"hemato1-splenomegaly:e4":{"s":2,"u":["Signs: moves with respiration, notched anterior edge.","On examination, two signs identify the spleen: it moves with respiration and has a notched anterior edge ."],"dp":[]},"hemato1-splenomegaly:e5":{"s":2,"u":["Differential: left kidney, pancreatic tail, left colic angle, stomach tumours.","Differential diagnosis of a left upper quadrant mass: enlarged left kidney , tumour of the tail of the pancreas , of the left colic angle or of the stomach's left edge ."],"dp":[]},"hemato1-splenomegaly:e6":{"s":3,"u":["Mechanisms: hyperplasia, congestion, infiltration.","Three mechanisms: hyperplasia or hypertrophy (reticulo-endothelial or immune), congestion (abnormal portal flow) and infiltration (abnormal cells, lymphoma)."],"dp":[]},"hemato1-splenomegaly:e7":{"s":3,"u":["CBC + film + abdominal ultrasound explain ~90% of cases.","Approach: history (Mediterranean origin or consanguinity → thalassaemia; tropical travel → malaria; fever → infection; liver disease or ascites → congestion; anaemia and jaundice → haemoglobinopathy; lymph nodes → lymphoma), examination , then CBC with blood film and abdominal ultrasound , which together explain about 90% of splenomegalies.","Ultrasound clues: wide portal vein with ascites (portal hypertension), abdominal nodes (lymphoma), splenic tumours."],"dp":[]},"hemato1-splenomegaly:e10":{"s":4,"u":["Infiltration: CML, myelofibrosis, CLL, lymphoma; Gaucher, amyloidosis.","Infiltrative : malignant (AML, CML , myelofibrosis, ALL, CLL, lymphoma; primary splenic cancer such as angiosarcoma and metastases are rare) and non-malignant (Gaucher, Niemann-Pick, amyloidosis, cysts, haemangioma)."],"dp":[]},"hemato1-splenomegaly:e8":{"s":4,"u":["Infections: mononucleosis, endocarditis, typhoid, brucellosis, malaria, kala-azar.","Infections : viral (infectious mononucleosis, CMV, HIV), bacterial (endocarditis, septicaemia, typhoid, brucellosis), parasitic ( malaria, kala-azar , trypanosomiasis)."],"dp":[]},"hemato1-splenomegaly:e9":{"s":4,"u":["Congestion: cirrhosis, portal thrombosis, Budd-Chiari, right heart failure.","Congestive : intrahepatic portal hypertension ( cirrhosis ), extrahepatic (portal thrombosis, venous malformation, Budd-Chiari), right heart failure."],"dp":[]}},"meta":{"zys23r":{"a":"recall","vg":"hemato1-splenomegaly:e1/recall/1"},"1dep6gw":{"a":"recall","vg":"hemato1-splenomegaly:e0/recall/1"},"1nczwv5":{"a":"recall","vg":"hemato1-splenomegaly:e0/recall/2"},"1md3vie":{"a":"recall","vg":"hemato1-splenomegaly:e4/recall/1"},"v7bspj":{"a":"recall","vg":"hemato1-splenomegaly:e2/recall/1"},"1y4o8kh":{"a":"recall","vg":"hemato1-splenomegaly:e3/recall/1"},"1ttyuwv":{"a":"recall","vg":"hemato1-splenomegaly:e3/recall/2"},"dfymuz":{"a":"recall","vg":"hemato1-splenomegaly:e5/recall/1"},"1vsb7jn":{"a":"relationship","vg":"hemato1-splenomegaly:e7/relationship/1"},"h12v2v":{"a":"recall","vg":"hemato1-splenomegaly:e7/recall/1"},"10fx7e8":{"a":"recall","vg":"hemato1-splenomegaly:e7/recall/2"},"ow5i78":{"a":"recall","vg":"hemato1-splenomegaly:e8/recall/1"},"1qmit6h":{"a":"recall","vg":"hemato1-splenomegaly:e9/recall/1"},"oxq4r6":{"a":"relationship","vg":"hemato1-splenomegaly:e10/relationship/1"}},"explRev":"b17d22d79fd1"};
